// swift-tools-version: 5.9
import PackageDescription

let package = Package(
    name: "OsonaiSDK",
    platforms: [.iOS(.v15)],
    products: [.library(name: "OsonaiSDK", targets: ["OsonaiSDK"])],
    targets: [
        // Resources/osonai-chat.html is generated by packages/embed (npm run build -w @osonai/embed).
        // Resources/PrivacyInfo.xcprivacy is the SDK's App Store privacy manifest.
        .target(name: "OsonaiSDK", resources: [.copy("Resources/osonai-chat.html"), .copy("Resources/PrivacyInfo.xcprivacy")]),
    ]
)
